"""Generate the offline visual-learning dataset. Sources use PDF file pages."""
from pathlib import Path
import json
import re

ROOT = Path(__file__).resolve().parent
manifest = json.loads((ROOT / 'biblioteca/2026/programa/manifest.json').read_text(encoding='utf-8'))
mods = {}
for d in manifest['documentos']:
    hit = re.search(r'Modulo-(\d)', d['titulo'])
    if hit:
        m = int(hit[1])
        mods[m] = {'id': m, 'name': ['Organización del Estado', 'Poder Judicial de Mendoza', 'Derechos Humanos', 'Violencia de Género', 'Servicio de Justicia'][m-1], 'color': ['#285dab','#0b7274','#7354a5','#af466c','#936c17'][m-1], 'file': d['archivo'], 'url': d['url'], 'pages': d['paginas']}

cards = []
def card(m, title, question, answer, page, cue, note=''):
    c = {'id': f'm{m}-{sum(x['module']==m for x in cards)+1:02}', 'module':m, 'title':title, 'question':question, 'answer':answer, 'page':page, 'cue':cue, 'note':note, 'sources':[{'module':m,'page':page}]}
    cards.append(c)
    return c

# 24 cards in each module. Questions, explanations and memory cues are original.
card(1,'Cuatro elementos','¿Qué cuatro elementos componen el Estado?','Territorio, población, poder y gobierno. Territorio es la base espacial; población, el conjunto humano; poder, la capacidad estatal; gobierno, los órganos que lo ejercen.',2,'Ubicá un mapa, sus habitantes, una capacidad de decisión y los órganos que la ejercen. Son cuatro piezas distintas.')
card(1,'Estado de Derecho','¿Qué limita jurídicamente al gobierno en un Estado de Derecho?','Un ordenamiento positivo regula su organización y actuación y los derechos y libertades de los habitantes. La autoridad está sometida a normas.',3,'Imaginá al gobierno dentro del marco de la Constitución: el marco también lo limita.')
card(1,'Constituyente y constituido','¿En qué se diferencia el poder constituyente de los poderes constituidos?','El constituyente establece o reforma la Constitución. Los poderes constituidos nacen de ella y ejercen las competencias que reciben.',3,'Crear el tablero / actuar dentro del tablero. La imagen es una ayuda propia, no una definición jurídica.')
card(1,'Supremacía','¿Qué exige la supremacía constitucional a las normas inferiores?','Que sean compatibles con la Constitución y el bloque constitucional aplicable. Una norma de rango inferior no puede contradecir válidamente la superior.',4,'Escalera normativa: cada peldaño inferior debe respetar el superior.')
card(1,'Representativa','¿Qué significa la forma representativa?','El pueblo ejerce el gobierno mediante representantes. La iniciativa y consulta popular complementan la participación según la Constitución.',6,'La ciudadanía elige quién ocupa el espacio de decisión.')
card(1,'Republicana','Nombrá rasgos de la forma republicana.','Soberanía popular, igualdad ante la ley, elección y periodicidad de autoridades políticas, responsabilidad, publicidad de los actos y división de poderes.',7,'Las decisiones tienen autor responsable y pueden verse: responsabilidad + publicidad. No trasladar el mandato político a los jueces.')
card(1,'Federal','¿Qué distribuye territorialmente el federalismo argentino?','Distribuye el poder entre el gobierno federal y entidades locales autónomas. El módulo distingue Nación, provincias, CABA y municipios.',8,'Cuatro escalas territoriales; no son cuatro oficinas subordinadas entre sí en toda materia.')
card(1,'Autonomía y autarquía','¿Cuál es la diferencia entre autonomía y autarquía?','Autonomía comprende autogobierno y normas propias. Autarquía se refiere a autoadministración. Las provincias son autónomas, no soberanas.',9,'Autonomía: decidir reglas propias. Autarquía: administrar. Recordá que no significan lo mismo.')
card(1,'Congreso','¿Por qué el Congreso es bicameral, colegiado y complejo?','Tiene dos cámaras; está integrado por muchas personas; y posee órganos internos diferenciados. Diputados representa al pueblo y Senado a provincias y CABA.',11,'Dos salas, varias personas, organización interna: cada rasgo responde a una pregunta distinta.')
card(1,'Diputados y Senado','¿Qué pares edad–ciudadanía–mandato presenta la tabla nacional?','Diputados: 25 años, 4 de ciudadanía y 4 de mandato. Senado: 30 años, 6 de ciudadanía y 6 de mandato. Ambos: nativo del distrito o 2 años de residencia inmediata.',12,'Dos renglones: D = 25 / 4 / 4; S = 30 / 6 / 6. No mezcles edad y años de ejercicio.')
card(1,'Ejecutivo nacional','¿Quién ejerce el Ejecutivo nacional y cuánto dura el mandato?','El presidente ejerce el Poder Ejecutivo. El mandato dura cuatro años; el art. 90 regula una reelección consecutiva o sucesión recíproca y el intervalo de un período posterior.',14,'Cuatro años y una continuidad permitida: luego aparece el intervalo constitucional.')
card(1,'DNU','¿Qué cuatro materias quedan excluidas de los DNU?','Penal, tributaria, electoral y régimen de partidos políticos. El DNU es una excepción constitucional, no una facultad ordinaria para reemplazar al Congreso.',17,'Pensá en castigos, tributos, elecciones y partidos: cuatro asuntos especialmente vedados.')
card(1,'Jurisdicción','¿Qué expresa la función jurisdiccional?','La potestad de resolver controversias aplicando el Derecho y hacer cumplir las decisiones, con independencia e imparcialidad.',21,'Un conflicto llega, una decisión lo resuelve y puede hacerse cumplir.')
card(1,'Independencia judicial','¿Qué dos garantías de independencia destaca el material?','Inamovilidad mientras dure la buena conducta e intangibilidad de remuneración. No excluyen los procedimientos constitucionales de remoción.',22,'Cargo y remuneración protegidos; responsabilidad y remoción siguen existiendo.')
card(1,'Federal y provincial','¿Un juzgado federal situado en Mendoza integra el Poder Judicial provincial?','No. La ubicación geográfica no cambia el orden jurisdiccional. Coexisten justicia federal y justicia provincial con competencias propias.',23,'Separá dónde está el edificio de a qué orden pertenece.')
card(1,'Misión y visión','¿Cómo distinguir misión de visión institucional?','Misión es la razón de ser: afianzar justicia y derechos mediante acceso y servicio. Visión es el futuro buscado: un Poder Judicial accesible, eficaz y orientado a proteger derechos.',26,'Misión = propósito presente; visión = destino. Leé también los recuadros gráficos originales.')
card(1,'Ministerios públicos','¿Qué distingue al MP Fiscal del MP de la Defensa y Pupilar?','El Fiscal defiende la legalidad y los intereses generales. La Defensa y Pupilar brinda asistencia técnico-jurídica para garantizar acceso a justicia, especialmente a personas en vulnerabilidad.',27,'Fiscal: legalidad e interés general. Defensa: asistencia y defensa técnica. No intercambiar roles.')
card(1,'Tres funciones de la Corte','¿Qué funciones de la Suprema Corte distingue el módulo?','Administrativa y de superintendencia; jurisdiccional; dirimente. Organizar personal, decidir una causa y ejercer potestades prudenciales para resolver conflictos responden a funciones distintas.',28,'Tres puertas en la misma Corte: organizar / juzgar / dirimir. La dirimente no se equipara automáticamente a juzgar.')
card(1,'Jerarquía','¿Qué relación describe la jerarquía administrativa?','Supremacía y subordinación entre órganos de una misma persona jurídica. Línea es la cadena vertical y grado es la ubicación del órgano en esa cadena.',31,'Dibujá una línea con escalones: la línea une; el grado ubica.')
card(1,'Competencia','¿La competencia pertenece a la persona funcionaria o al órgano?','Al órgano o cargo. Son las atribuciones que puede y debe ejercer legítimamente. Es irrenunciable, con las reglas y excepciones legales sobre delegación o avocación.',32,'La llave pertenece al cargo, no al bolsillo personal de quien lo ocupa.')
card(1,'Acto administrativo','¿Qué define al acto administrativo?','Declaración unilateral efectuada en ejercicio de función administrativa que produce efectos jurídicos individuales y directos.',32,'Una declaración + función administrativa + efecto individual directo: comprobar los tres componentes.')
card(1,'Ejecutividad y ejecutoriedad','¿Por qué ejecutividad y ejecutoriedad no son sinónimos?','Ejecutividad es obligatoriedad y exigibilidad del acto regular notificado. Ejecutoriedad es la posibilidad jurídicamente habilitada de ejecutarlo por sí, sin previa habilitación judicial.',34,'Obligatorio / ejecutable por la Administración. El segundo requiere habilitación y límites legales.')['sources'].append({'module':1,'page':35})
card(1,'Vicios del acto','¿Qué consecuencias corresponden a muy leve, leve, grave y grosero?','Muy leve: no afecta validez. Leve: anulabilidad. Grave: nulidad. Grosero: inexistencia. La clasificación exige valorar circunstancias y gravedad.',36,'Cuatro escalones crecientes: válido / anulable / nulo / inexistente. No aplicar sin examinar el caso.')
card(1,'Lecturas obligatorias','¿Qué remisiones obligatorias agrega el punto 1.6?','Reglamento del Poder Judicial, arts. 3 y 13; Acordada 15422; capítulo III del Decreto Ley 560/73; Ley 9665. La residencia del reglamento fue ampliada a 100 km y no se exige cumplirla al rendir.',39,'Una hoja de remisiones es parte del programa: módulo + reglamento + modificatoria + estatuto + ley nueva. No alcanza con el resumen.')

card(2,'Proceso','¿Para qué sirve el proceso y cuál es su doble función?','Es un medio pacífico de debate para resolver un conflicto: permite obtener solución estatal (función privada) y sustituye la fuerza privada por una garantía institucional (función pública).',2,'Del conflicto a una respuesta institucional: la paz social y la solución particular conviven.')
card(2,'Partes y auxiliares','¿Un testigo o perito es parte por colaborar con la prueba?','No. Actor y demandado sostienen pretensiones enfrentadas. El testigo aporta hechos y el perito conocimiento especializado; esa colaboración no los convierte en partes.',3,'Dos lados del conflicto y colaboradores de la prueba: ubicarlos en lugares distintos.')
card(2,'Conocimiento y monitorio','¿Qué diferencia estructural hay entre conocimiento y monitorio?','En conocimiento se debate y prueba antes de la sentencia de fondo. El monitorio comienza con una sentencia sobre base documental y ofrece después oportunidad de oposición.',4,'Conocimiento: debate → decisión. Monitorio: decisión inicial → posible oposición. Son esquemas de estudio, no todas las etapas de cada vía.')
card(2,'Cautelar','¿Qué fin tiene una medida cautelar?','Asegurar que el resultado de otro proceso no se frustre. Normalmente se cumple sin audiencia previa del afectado y después se notifica; no elimina la impugnación posterior.',4,'Protege el resultado futuro; no confundir asegurar con decidir definitivamente.')
card(2,'Amparo, corpus y data','¿Qué derecho orienta a cada vía: amparo, hábeas corpus, hábeas data?','Amparo: derecho constitucional frente a arbitrariedad o ilegalidad manifiesta. Hábeas corpus: libertad individual. Hábeas data: datos personales, su conocimiento y corrección cuando corresponda.',5,'Tres objetos: derecho / libertad física / datos. El objeto, no el nombre parecido, orienta la distinción.')
card(2,'Cargo','¿Qué acredita el cargo de un escrito?','La presentación, con fecha, hora y datos significativos. No es la carátula que identifica la causa ni la resolución que contiene la decisión.',7,'Cargo = cuándo entró. Carátula = qué causa. Resolución = qué decidió el órgano.')
card(2,'Decreto, auto, sentencia','¿Qué función cumple cada resolución civil?','Decreto: desarrollo o trámite. Auto: cuestiones que no corresponden a sentencia definitiva. Sentencia: decisión del fondo. Los plazos generales tienen excepciones expresas.',7,'Mover / resolver una cuestión / decidir el fondo. Identificá el contenido antes de memorizar un plazo.')
card(2,'Audiencia inicial civil','¿Qué se hace en la audiencia inicial civil?','Intentar conciliar, sanear el proceso, delimitar hechos y decidir admisión y producción de prueba. Debe dirigirla indelegablemente el juez.',8,'Preparar el terreno del debate: ordenar qué se discute y qué se prueba.')
card(2,'Prueba y alegato','¿Qué distingue la prueba del alegato?','La prueba procura acreditar hechos. El alegato argumenta qué conclusión debe extraerse de lo probado. El alegato no sustituye la falta de prueba.',9,'Prueba = elementos; alegato = razonamiento sobre esos elementos.')
card(2,'Bus Federal','¿Para qué sirve el Bus Federal de Justicia?','Para comunicaciones interjurisdiccionales digitales. Oficinas derivadoras centralizan envío/recepción; el uso de la plataforma no elimina formalidades, pagos ni vías alternativas ante fallas.',11,'Un puente entre jurisdicciones: transporta comunicaciones, no dicta decisiones.')
card(2,'BLSG','¿Para qué sirve el beneficio de litigar sin gastos?','Facilita acceso a justicia a quien no puede afrontar gastos. El módulo incorpora trámite automatizado con información socioeconómica y vía incidental; el informe es un insumo del trámite.',17,'La barrera económica no debe cerrar la puerta. Consultar datos requiere habilitación institucional.')
card(2,'Competencia y cuantía','¿Cómo calcula el módulo la cuantía civil/Paz?','Por capital nominal reclamado, sin intereses ni accesorios. En responsabilidad civil y consumo, el material usa 20 JUS como frontera Paz/Civil.',27,'Separá capital de accesorios antes de comparar el límite. No uses pesos históricos de 2023.')
card(2,'Apremio','¿Qué es el apremio?','Una estructura monitoria para el cobro compulsivo de créditos tributarios y otros créditos legalmente encomendados, con título suficiente y defensas previstas para esa vía.',42,'Cobro con título + defensa propia de esa estructura; no es cualquier demanda de conocimiento.')
card(2,'Preventivo y quiebra','¿Qué distingue al concurso preventivo de la quiebra?','El preventivo busca superar la insolvencia mediante acuerdo con acreedores. La quiebra persigue liquidación y distribución, con desapoderamiento según régimen legal.',53,'Dos salidas colectivas de la insolvencia: acordar / liquidar. No equivalen a cobrar un acreedor aislado.')
card(2,'Síndico','¿Qué función cumple el síndico concursal?','Es un órgano técnico necesario: vigila administración en preventivo, administra y liquida en quiebra conforme al régimen y emite dictámenes; no sustituye al juez.',56,'Juez decide; síndico interviene técnicamente en el concurso. Son roles diferenciados.')
card(2,'Familia','¿Qué criterios orientan el abordaje de NNA en familia?','Interés superior, autonomía progresiva y derecho a ser oído. Deben atenderse circunstancias y capacidad progresiva, evitando reducir el análisis a una edad aislada.',64,'Interés / autonomía / escucha: la persona menor de edad participa como sujeto de derechos.')
card(2,'Protectorio laboral','¿Qué busca el principio protectorio laboral?','Compensar jurídicamente la desigualdad de la relación laboral mediante reglas como in dubio pro operario, norma más favorable y condición más beneficiosa.',72,'No son tres nombres del mismo supuesto: duda interpretativa, comparación normativa y condición adquirida se distinguen.')
card(2,'Vías laborales previas','¿Qué vías previas distingue el material para despido y riesgos del trabajo?','Despido y rubros derivados: Oficina de Conciliación Laboral. Accidente o enfermedad profesional: Comisión Médica en el régimen explicado. No intercambiar recorridos.',76,'Dos puertas según conflicto: OCL / Comisión Médica. Revisar los supuestos y excepciones oficiales.')
card(2,'Garantías penales','¿Puede la prisión cautelar usarse como una pena anticipada?','No. El estado de inocencia subsiste hasta sentencia firme. Acusación no equivale a culpabilidad y las medidas cautelares tienen finalidad y requisitos propios.',90,'Imputación / cautela / condena son tres casilleros diferentes.')
card(2,'Teoría del delito','¿Qué cuatro presupuestos ordenan el análisis clásico del delito?','Conducta, tipicidad, antijuridicidad y culpabilidad. Un hecho típico puede estar justificado; tipicidad no demuestra por sí sola culpabilidad.',92,'Cuatro filtros: hecho exteriorizado / encaje legal / ausencia de permiso / reproche personal.')
card(2,'Fiscal, juez y OGAP','¿Cómo se separan investigación, decisión y organización en el modelo penal?','Fiscal investiga y acusa. Juez controla legalidad y decide con imparcialidad. OGAP administra agenda, salas y recursos; no resuelve prisión preventiva ni sentencias.',93,'Investigar / decidir / organizar: tres trabajos que no se intercambian.')['sources'].append({'module':2,'page':94})
card(2,'Juicio por jurados','¿Cuántos integrantes tiene y qué decide el jurado?','12 titulares y 4 suplentes, con paridad. El jurado decide hechos y veredicto; el juez técnico dirige y resuelve cuestiones jurídicas. El módulo exige unanimidad de titulares para el veredicto.',96,'12 deciden + 4 suplen. Hechos/veredicto y derecho/dirección son responsabilidades diferenciadas.')['sources'].append({'module':2,'page':99})
card(2,'Penal juvenil 2026','¿Qué franja de edad presenta el módulo 2026 para punibilidad juvenil?','Desde 14 años hasta las cero horas del día en que se cumplen 18, conforme a la nueva ley citada. Estar en la franja no implica culpabilidad probada ni prisión obligatoria.',102,'Una franja temporal, no un veredicto. No reutilizar 16–18 del régimen anterior; leer también los anexos nuevos de p. 109.')['sources'].append({'module':2,'page':109})
card(2,'Legajo juvenil','¿La consulta provincial de LeD vuelve público un legajo juvenil?','No. El módulo dispone que el legajo penal juvenil es privado. La interoperabilidad y trazabilidad no autorizan acceso público indiscriminado.',108,'Una red puede conectar oficinas sin abrir la información a todo el mundo.')

card(3,'Dignidad','¿La dignidad depende de virtudes, nacionalidad o buena conducta?','No. Es inherente a toda persona humana y fundamento de los derechos humanos. No se otorga como premio ni se pierde por cometer un delito.',6,'La persona va primero; su dignidad no es una medalla que el Estado entrega.')
card(3,'Garante principal','¿Quién es titular y quién es el principal garante de los derechos humanos?','La persona es titular; el Estado es primer y principal garante. Las obligaciones abarcan respeto, protección y garantía.',3,'Persona con derechos / Estado con obligaciones: dos posiciones de la relación.')
card(3,'Subsidiariedad','¿Cómo se relaciona la protección internacional con la interna?','La internacional es una garantía adicional y subsidiaria de los mecanismos nacionales. No sustituye sin más a los recursos internos.',3,'Una segunda red de protección, adicional a la primera.')
card(3,'Universal y regional','¿Qué sistemas internacionales menciona el módulo para Argentina?','Sistema universal, en la ONU, y sistema regional interamericano, en la OEA. Ambos tienen órganos y mecanismos propios.',4,'Dos círculos: mundo / región. No confundir ONU con OEA.')
card(3,'Jerarquía de tratados','¿Todos los tratados de derechos humanos tienen jerarquía constitucional?','No automáticamente. La tienen los enumerados en el art. 75 inc. 22 CN y los elevados por el procedimiento constitucional. Todos los ratificados tienen jerarquía superior a las leyes.',4,'Constitucional y supralegal no son la misma altura.')['sources'].append({'module':3,'page':5})
card(3,'Efectividad','¿Qué agrega la efectividad al reconocimiento de un derecho?','Que pueda gozarse y ejercerse plenamente, con exigibilidad y operatividad. No basta declararlo como una aspiración.',6,'Del papel a la posibilidad real de ejercer y reclamar.')
card(3,'Progresividad','¿Qué dirección impone la progresividad?','Avanzar hacia mayor reconocimiento, protección y realización de derechos. La prohibición de regresividad impide, al menos en principio, retroceder sobre lo alcanzado.',6,'Una trayectoria de protección creciente; revisar un retroceso requiere fundamento, no tratarlo como libre opción.')['sources'].append({'module':3,'page':7})
card(3,'Pro personae','¿Cómo orienta la selección e interpretación de normas el principio pro personae?','Hacia la protección más amplia de derechos y la restricción menos intensa. Opera tanto al elegir entre normas aplicables como al interpretar una norma.',7,'Abrir protección / estrechar restricción. La flecha apunta a la persona protegida.')
card(3,'Igualdad','¿Igualdad exige dar idéntico trato ante cualquier situación?','No. Reconoce diferencias y puede requerir medidas frente a desigualdad estructural. No discriminación impide diferencias que lesionen derechos.',8,'Equilibrar acceso puede requerir remover una barrera específica.')
card(3,'Acción positiva','¿Qué fin tienen las medidas de acción positiva?','Generar condiciones que compensen desigualdad estructural histórica. El módulo las caracteriza como temporales y orientadas al igual goce de derechos.',8,'Un apoyo dirigido a una barrera, no una etiqueta permanente de inferioridad.')
card(3,'Universalidad','¿A quiénes y en qué lugares pertenecen los derechos humanos?','A todas las personas, en todo momento y lugar, sin distinciones que nieguen su condición humana.',8,'Toda persona atraviesa el mismo umbral de titularidad.')
card(3,'Interdependencia','¿Por qué negar un derecho puede afectar otros?','Los derechos son indivisibles, interdependientes, integrales y complementarios: forman un sistema de protección de una vida digna.',8,'Una red: cortar un vínculo puede tensionar los demás.')
card(3,'Irrenunciables e imprescriptibles','¿Qué significan irrenunciabilidad e imprescriptibilidad en este material?','No se puede obligar a renunciar a derechos y libertades; no se pierden por el transcurso del tiempo ni por falta de ejercicio.',9,'Ni firma forzada ni reloj borran la titularidad de derechos humanos.')
card(3,'Inalienables','¿Los derechos humanos pueden comercializarse o transferirse?','No. Son atributos inherentes a la persona y no pueden cederse, venderse o transferirse.',9,'Una persona no pone en venta su titularidad de derechos.')
card(3,'Clasificación didáctica','¿Clasificar derechos en civiles, sociales y colectivos permite jerarquizarlos?','No. La clasificación es pedagógica e histórica; no reduce importancia, exigibilidad ni fuerza vinculante de ninguna categoría.',9,'Estantes para ordenar el estudio, no un podio de derechos.')
card(3,'Respetar','¿Qué exige la obligación estatal de respetar?','Abstenerse de interferir ilegítimamente en el ejercicio de derechos. Es la dimensión negativa, sin que los demás deberes se reduzcan a abstenerse.',10,'Primero, no obstaculizar ni vulnerar.')
card(3,'Garantizar','¿La obligación de garantizar se cumple sólo con no dañar?','No. Requiere medidas positivas para hacer posible el goce efectivo, organizar mecanismos de protección y responder a las violaciones.',11,'Hacer que el derecho pueda ejercerse: organizar y actuar.')
card(3,'Proteger','¿Qué alcanza la protección frente a terceros?','Exige medidas para evitar que particulares vulneren derechos y respuestas adecuadas ante esas afectaciones. No toda afectación se agota en un agente estatal directo.',12,'El Estado debe cuidar también frente al daño de terceros.')
card(3,'Investigar y reparar','¿Qué deberes aparecen ante violaciones de derechos?','Prevenir, investigar, sancionar cuando corresponda y reparar, dentro de las obligaciones de garantía. No basta un reconocimiento formal sin respuesta efectiva.',13,'Antes: prevenir. Después: investigar, sancionar y reparar; cada verbo tiene una función.')
card(3,'Vulnerabilidad situada','¿La vulnerabilidad es una cualidad natural e inmutable de una persona?','No. Se vincula a contextos y condiciones estructurales de desigualdad, es dinámica y modificable. Se habla de personas o grupos en situación de vulnerabilidad.',16,'Poner el foco en las barreras y el contexto, no fijar una etiqueta esencial.')
card(3,'Discriminación estructural','¿Qué exige reconocer patrones de desigualdad estructural?','No limitarse a un caso aislado: identificar barreras y adoptar acciones para revertir desigualdades en el acceso y ejercicio de derechos.',17,'Una dificultad repetida en un grupo pide mirar también el sistema que la produce.')
card(3,'Enfoque de derechos','¿Qué cambia el enfoque de derechos en una política pública?','Las personas se consideran titulares con derechos exigibles y el Estado responsable de cumplir obligaciones, en cada acción, decisión y política.',18,'De receptor de ayuda a titular que puede exigir.')
card(3,'Acceso integral','¿Acceso a justicia equivale solamente a poder entrar a un tribunal?','No. El modelo integral incluye ingreso, permanencia, participación y una respuesta efectiva, con eliminación de barreras a lo largo de la trayectoria.',21,'Puerta, recorrido y respuesta: las tres partes del viaje importan.')
card(3,'Barreras de género','¿Por qué una barrera institucional puede afectar más a mujeres en vulnerabilidad?','La desigualdad y discriminación estructural se combinan con otras barreras. El enfoque exige reconocer el contexto y mejorar las condiciones reales de acceso.',22,'Barreras que se superponen: mirar la combinación, sin presumir experiencias idénticas.')

card(4,'Perspectiva de género','¿Qué permite observar la perspectiva de género?','Relaciones de poder, desigualdades y sesgos asociados al género para evitar reproducirlos en decisiones y prácticas institucionales.',2,'Un lente hace visible un sesgo; no agrega una preferencia arbitraria.')
card(4,'Interseccionalidad','¿Qué analiza la interseccionalidad?','Cómo se entrecruzan género y otras condiciones o ejes de desigualdad, produciendo experiencias específicas que no se explican por un factor aislado.',2,'Cruce de caminos, no suma mecánica de etiquetas.')
card(4,'Sexo y género','¿En qué se diferencia sexo de género en el módulo?','Sexo refiere a características biológicas. Género, a una construcción sociohistórica y dinámica de roles y características atribuidas; es relacional y modificable.',3,'Cuerpo / atribuciones sociales: dos dimensiones que no deben confundirse.')
card(4,'Estereotipos','¿Qué hace un estereotipo de género?','Prescribe lo esperable o deseable para cada sexo y sanciona socialmente a quien se aparta. No es una descripción neutral de cada persona.',3,'Una plantilla sobre las personas borra diferencias y genera expectativas obligatorias.')
card(4,'Machismo y sexismo','¿Cómo distingue el módulo machismo de sexismo?','Machismo: creencia en superioridad del varón. Sexismo: métodos y mecanismos culturales o institucionales que mantienen subordinación y desigualdad.',3,'Creencia de superioridad / mecanismos que la sostienen.')
card(4,'Orientación','¿Qué dimensión responde a «quién me atrae»?','La orientación sexual: atracción emocional, afectiva y sexual. No permite inferir identidad o expresión de género.',4,'Atracción no es autopercepción ni apariencia.')
card(4,'Identidad','¿Qué dimensión responde a «cómo me autopercibo»?','La identidad de género: vivencia interna e individual, coincida o no con el sexo asignado al nacer.',4,'El centro es la vivencia de la persona, no una lectura externa.')
card(4,'Expresión','¿Qué dimensión responde a «cómo me muestro»?','La expresión de género: manifestaciones externas como vestimenta, peinado, lenguaje corporal o estilo. No autoriza a deducir orientación.',4,'La expresión es visible; identidad y atracción no se deducen de la ropa.')
card(4,'Hetero y cisnormatividad','¿Qué presupone cada normatividad?','Heteronormatividad: heterosexualidad como única forma válida. Cisnormatividad: que toda identidad coincide con el sexo asignado al nacer.',4,'Una presupone atracción; otra, identidad. Identificá la dimensión de cada supuesto.')
card(4,'Ley 26743','¿Se exige cirugía, hormonas o diagnóstico para la rectificación registral resumida?','No. El módulo excluye esos requisitos. La ley reconoce identidad autopercibida y trato conforme a ella; consultar el articulado para todos los requisitos del trámite.',5,'Reconocimiento de identidad no es un examen médico.')
card(4,'Violencia directa e indirecta','¿Puede haber violencia sin una agresión física?','Sí. Incluye acciones u omisiones basadas en desigualdad de poder; la indirecta comprende prácticas o criterios discriminatorios que colocan a la mujer en desventaja.',5,'Mirar conducta, omisión y efecto; no buscar únicamente un golpe.')
card(4,'Tipo y modalidad','¿Cuál es la diferencia entre tipo y modalidad de violencia?','Tipo describe la forma del daño o afectación; modalidad identifica el ámbito o contexto de manifestación. Un mismo hecho puede combinar tipos y una modalidad.',5,'Tipo = qué daño. Modalidad = en qué contexto. Son dos ejes que se cruzan.')['sources'].append({'module':4,'page':6})
card(4,'Física y psicológica','¿Qué distingue violencia física de psicológica?','La física actúa sobre el cuerpo y causa daño, dolor o riesgo. La psicológica afecta emocionalmente, autoestima o desarrollo mediante humillación, control, aislamiento u otras conductas.',5,'Cuerpo / vida emocional: pueden coexistir, no se excluyen.')
card(4,'Sexual y económica','¿Qué objetos protegen estos dos tipos?','La sexual afecta decidir libremente sobre vida sexual o reproductiva. La económica o patrimonial menoscaba recursos, ingresos o bienes.',5,'Decisión sexual / recursos y patrimonio: reconocer el objeto afectado.')
card(4,'Simbólica y política','¿Cómo distinguir violencia simbólica de política?','Simbólica: mensajes, signos y estereotipos que naturalizan dominación. Política: restricción de participación y representación pública en igualdad.',5,'Mensaje que subordina / participación que se impide. No confundir tipo política con modalidad pública política.')
card(4,'Doméstica','¿La modalidad doméstica exige convivencia actual?','No. Puede provenir de familiares o vínculos vigentes o finalizados, con o sin convivencia, según la definición del módulo.',6,'El vínculo importa; no sólo compartir techo hoy.')
card(4,'Laboral e institucional','¿Qué diferencia estas modalidades?','Laboral: discriminación, hostigamiento o desigualdad en el empleo. Institucional: agentes que retardan, obstaculizan o impiden acceso a derechos o políticas públicas.',6,'Empleo / acceso a derechos por acción institucional. El mismo hecho puede requerir más de una mirada.')
card(4,'Digital','¿Qué caracteriza la modalidad digital o telemática?','Se ejerce mediante TIC: difusión no consentida de material íntimo, ciberacoso, extorsión, odio misógino o ciberataques, según el módulo.',6,'El medio digital define el contexto; el daño puede ser psicológico, sexual, económico u otro.')
card(4,'Ciclo de violencia','¿Qué tres fases presenta el modelo de Walker?','Acumulación de tensión, explosión o descarga y luna de miel o arrepentimiento. Con el tiempo puede desaparecer la tercera fase y aumentar frecuencia y gravedad.',7,'Una secuencia ayuda a reconocer la dinámica; no usarla para negar violencia cuando un caso no repite exactamente el modelo.')
card(4,'Revictimización','¿Qué prácticas pueden revictimizar en una oficina?','Demoras injustificadas, derivaciones inconducentes, interrogatorios repetitivos, indagaciones privadas o exámenes superfluos y tratos deshumanizados.',8,'No hacer que el recorrido institucional agregue un nuevo daño.')
card(4,'Retractación','¿Retirar o no ratificar una denuncia obliga a cerrar una investigación de acción pública?','No. El MPF debe continuar de oficio; se analiza el contexto y se produce prueba independiente, sin amenazas a la persona retractada.',9,'Retractación no es botón de cierre: contexto, prueba y deber estatal.')
card(4,'Protocolo 30979','¿Quién aplica el protocolo de violencia laboral por género y a quién protege?','La Dirección de la Mujer, Género y Diversidad. Alcanza personal judicial sin importar cargo, antigüedad o contratación y contempla trabajo presencial y remoto en las cuatro circunscripciones.',9,'La protección cruza cargos y modalidades de trabajo.')
card(4,'Principios del protocolo','Nombrá los principios de actuación del protocolo resumido.','Dignidad, confidencialidad, no revictimización, gratuidad, celeridad e imparcialidad. Divulgar datos vulnera la confidencialidad.',9,'Seis condiciones del recorrido: digno, reservado, sin daño añadido, gratuito, célere e imparcial.')
card(4,'Medidas de resguardo','¿Qué ejemplos de resguardo inmediato menciona el módulo?','Separar espacios, trabajo remoto o traslado transitorio, flexibilidad horaria y licencia. No confundir estas medidas con sanción definitiva ni presumir consentimiento universal para compulsas.',10,'Proteger durante el trámite es distinto de resolver responsabilidad. Para compulsas: consultar original pp. 17–18.')
cards[-1]['sources'].append({'file':'biblioteca/2026/referencias/Protocolo-Violencia-Laboral-30979.pdf','page':17,'label':'Protocolo original'})

card(5,'Centro en la ciudadanía','¿Qué cambia al poner a la ciudadanía en el centro del servicio?','Se organiza la atención alrededor de necesidades y derechos reales: orientación, accesibilidad, transparencia, respeto y eficiencia, no sólo cumplimiento interno del trámite.',3,'El expediente tiene una persona alrededor; ordenar el servicio desde su necesidad.')
card(5,'Calidad','¿La calidad del servicio equivale únicamente a rapidez?','No. Integra respeto y empatía, accesibilidad, transparencia, participación y eficacia en la respuesta. Rapidez sin comprensión puede dejar la necesidad sin resolver.',4,'Un reloj no mide por sí solo si la persona entendió y pudo actuar.')
card(5,'Puerta de entrada','¿Por qué el agente es una puerta de entrada a la justicia?','Su trato y orientación conectan a la persona con el ejercicio de derechos y con la institución; la atención integra la tutela efectiva.',5,'La primera interacción puede abrir o cerrar el recorrido.')
card(5,'Experiencia integral','¿La experiencia de justicia se reduce a la sentencia?','No. Incluye la trayectoria completa de interacciones, expectativas y emociones desde búsqueda de información hasta finalización.',6,'Mirar toda la ruta, no sólo la última estación.')
card(5,'Búsqueda y formalización','¿Qué respuestas ayudan en búsqueda y formalización?','Búsqueda: información clara y señalización frente a incertidumbre. Formalización: explicar pasos y evitar tecnicismos frente a ansiedad y expectativas.',6,'Primero orientarse; después iniciar con pasos comprensibles.')
card(5,'Seguimiento y audiencia','¿Qué necesita una persona durante seguimiento y audiencia?','Seguimiento: conocer estado y plazos realistas. Audiencia: entender roles y desarrollo, con trato cálido frente a intimidación o miedo.',7,'En seguimiento pregunta dónde va; en audiencia quién hace qué.')
card(5,'Resolución y cierre','¿Cómo atender resolución y finalización?','Comunicar con empatía, explicar opciones y orientar el cierre sin trámites innecesarios. El resultado puede generar alivio o frustración.',7,'La decisión se explica; la salida se acompaña.')
card(5,'Lenguaje claro','¿Qué busca el lenguaje claro en la atención?','Que la información sea comprensible y útil: adaptar vocabulario, organizar ideas, explicar tecnicismos y comprobar comprensión sin perder precisión.',9,'Claro no es incompleto: el criterio es si la persona comprende qué hacer.')
card(5,'Comunicación no verbal','¿Qué debe concordar con las palabras al atender?','Postura, gestos, expresión facial, mirada, tono y distancia según la situación. La comunicación verbal y no verbal deben sostener un trato respetuoso.',11,'Un «te escucho» necesita una conducta que lo acompañe.')
card(5,'Escucha activa','¿Escuchar activamente consiste sólo en permanecer en silencio?','No. Requiere atención, empatía, preguntas pertinentes, reformulación y verificación de comprensión, sin juzgar ni interrumpir innecesariamente.',11,'Escuchar → reformular → verificar. La secuencia es una ayuda práctica propia.')
card(5,'Regla contextual','¿La referencia a Mehrabian significa que sólo 7% de cualquier información jurídica depende de palabras?','No. El material la contextualiza a actitudes y sentimientos. No debe generalizarse a transmisión de contenido jurídico o instrucciones.',10,'Contexto antes que porcentaje: el significado de una norma sí depende de sus palabras.')
card(5,'Cuatro pilares','¿Cuáles son los cuatro pilares de atención?','Cortesía, respeto, eficiencia y resolución efectiva. Cada uno describe conductas observables, no sólo una intención amable.',14,'Saludar / dignificar / usar bien recursos / resolver u orientar el paso siguiente.')
card(5,'Derivación','¿Qué convierte una derivación en orientación útil?','Comprender la necesidad, explicar por qué y adónde se deriva, brindar información precisa y verificar dudas. Evitar enviar de oficina en oficina sin una dirección concreta.',16,'Un puente con destino y explicación, no una puerta que se cierra.')
card(5,'Quejas','¿Cómo abordar una queja?','Escuchar sin interrumpir, reconocer el problema o malestar, buscar solución o derivación pertinente, actuar y hacer seguimiento según el procedimiento descrito.',17,'La queja informa un fallo del recorrido y pide una respuesta, no una defensa automática de la oficina.')['sources'].append({'module':5,'page':18})
card(5,'Modelo social','¿Dónde sitúa las barreras el modelo social de discapacidad?','En la interacción entre personas y entornos con obstáculos. La institución debe remover barreras y proporcionar apoyos para participación en igualdad.',18,'Mirar la escalera, el formulario y el trato; no atribuir todo a la persona.')
card(5,'Diseño y ajustes','¿Qué distingue diseño universal de ajustes razonables?','Diseño universal: condiciones accesibles pensadas desde el inicio para el mayor número de personas. Ajustes razonables: modificaciones necesarias para un caso particular, sin carga desproporcionada.',19,'Preparar el entorno para muchos / adaptar lo necesario para una persona.')
card(5,'Cuatro dimensiones accesibles','¿Qué dimensiones de accesibilidad desarrolla el módulo?','Física; información y comunicación; actitudinal; tecnológica. No basta eliminar una escalera si los contenidos o el trato siguen excluyendo.',19,'Edificio / mensaje / trato / sistema: cuatro lugares donde buscar barreras.')['sources'].append({'module':5,'page':20})
card(5,'Accesibilidad actitudinal','¿Cómo evitar una barrera actitudinal?','Dirigirse a la persona, escuchar, no infantilizar ni presumir incapacidad y ofrecer ayuda sin imponerla. Adaptar el trato a necesidades expresadas.',20,'Preguntar y respetar autonomía antes de ayudar.')
card(5,'Personas mayores','¿Qué puede requerir una atención accesible a personas mayores?','Considerar barreras sensoriales, movilidad, tiempos y brecha digital, con alternativas y explicaciones claras, sin tratar a todas como dependientes.',21,'Tiempo, formato y alternativa; no suponer una misma necesidad por la edad.')
card(5,'Niñez y cultura','¿Qué cambia al atender niñez o personas con otra lengua/cultura?','Usar comunicación adecuada, reconocer participación y necesidades; procurar intérpretes o apoyos cuando corresponda y evitar estereotipos.',22,'Adaptar el canal para escuchar a la persona, no cambiar su derecho a ser escuchada.')['sources'].append({'module':5,'page':23})
card(5,'Cinco componentes','¿Cuáles son los cinco componentes de una competencia?','Saber; saber hacer; saber ser/estar; querer hacer; poder hacer. Conocimiento, habilidad, actitud, motivación y condiciones de realización se complementan.',24,'Una mano de cinco apoyos: conocer, aplicar, actuar, querer y contar con medios.')
card(5,'Iceberg','¿Qué enseña el modelo del iceberg de competencias?','Conocimientos y habilidades son más visibles. Actitudes, valores y motivaciones son menos visibles y también influyen en el desempeño.',25,'Lo visible no agota la competencia; mirar también lo que sostiene la conducta.')
card(5,'Aprendizaje consciente','¿Qué secuencia didáctica de aprendizaje presenta el módulo?','Incompetencia inconsciente, incompetencia consciente, competencia consciente y competencia inconsciente. Reconocer una falta permite practicar de manera deliberada.',27,'No sé que falta → detecto la falta → hago con atención → desempeño automatizado. No usarlo como diagnóstico rígido de una persona.')
card(5,'Ética y barreras','¿Cómo conecta la ética del agente con el acceso a justicia?','Integridad, responsabilidad, respeto y confidencialidad deben traducirse en acciones que eviten barreras económicas, culturales, geográficas, de género y discapacidad.',28,'Un valor se recuerda mejor unido a una acción concreta que abre el acceso.')['sources'].append({'module':5,'page':29})

