def node(cid, label=None, detail=None):
    c = byid[cid]
    return {'id':cid,'label':label or c['title'],'detail':detail or c['answer'],'sources':c['sources']}
def extra(mid, nid, label, detail, page):
    return {'id':nid,'label':label,'detail':detail,'sources':[{'module':mid,'page':page}]}
maps=[]
def concept_map(id,m,title,root,rootpage,lead,groups,hint,kind='concept'):
    maps.append({'id':id,'module':m,'title':title,'root':root,'rootSources':[{'module':m,'page':rootpage}],'lead':lead,'groups':groups,'hint':hint,'kind':kind})
def group(title, relation, nodes): return {'title':title,'relation':relation,'nodes':nodes}

